css:
.print-format {
	page-width: 100mm;
	page-height: 150mm;
	margin-top: 3mm;
	margin-bottom: 3mm;
	margin-left: 3mm;
	margin-right: 3mm;
	padding: 0;
	max-width: 94mm;
	font-size: 11px;
	color: #000;
}
.label { border: 1.5px solid #000; padding: 6px; }
.label .top { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid #000; padding-bottom: 4px; }
.label .courier { font-size: 16px; font-weight: 700; text-transform: uppercase; }
.label .code { text-align: center; padding: 6px 0; border-bottom: 1px solid #000; }
.label .code svg { max-width: 100%; height: auto; }
.label .hint { font-size: 9px; }
.label .block { padding: 5px 0; border-bottom: 1px solid #000; }
.label .title { font-size: 9px; text-transform: uppercase; letter-spacing: .05em; }
.label .name { font-size: 15px; font-weight: 700; }
.label .big { font-size: 14px; font-weight: 700; }
.label .type { font-weight: 700; margin-top: 2px; }
.label .cod { display: flex; justify-content: space-between; align-items: center; border: 2px solid #000; margin: 6px 0; padding: 6px 8px; }
.label .cod strong { font-size: 20px; }
.label .small { font-size: 10px; }
.label .sender { border-bottom: 0; }
